import 'package:flutter_test/flutter_test.dart';
import 'package:memora/dual_world_engine.dart';
void main(){
 test('external books grant exact five points and preserve progress after return',(){final s=DualState();expect(s.addReadingBook('Libro','Autora',300,'Finanzas'),true);final key=DualState.bookKey('Libro','Autora');expect(s.logReading(key,30),500);expect(s.intelligence,5);expect(s.logReading(key,300),4500);expect(s.intelligence,10);expect(s.logReading(key,300),isNull);expect(s.returnToBeginning().readingLog[key]!['page'],300);});
 test('repeatable monster XP scales with level',(){final s=DualState();expect(s.victoryXp({'repeatable':true,'level':4,'hp':100},false),greaterThan(s.victoryXp({'repeatable':true,'level':1,'hp':20},true)));});
 test('reading awards five points per book without daily cap or repeats',(){final s=DualState();for(var b=0;b<30;b++){for(var p=0;p<5;p++){expect(s.pageReward(p,5),1);expect(s.read('b'+b.toString(),p,5),true);}}expect(s.intelligence,155);expect(s.read('b0',0,5),false);expect(s.returnToBeginning().intelligence,155);});
 test('return resets both worlds and retains intelligence and anti-duplicate records',(){final s=DualState();s.cash=300;s.skills.add('blade');s.strength=20;s.intelligence=25;s.workoutDate='2026-11-27';s.readPages['book']=5;s.deadStudents.add('x');s.spirits.add('fox');final r=s.returnToBeginning();expect(r.intelligence,25);expect(r.cash,0);expect(r.skills,isEmpty);expect(r.strength,4);expect(r.deadStudents,isEmpty);expect(r.spirits,isEmpty);expect(r.readPages['book'],5);expect(r.workoutDate,'2026-11-27');});
 test('spirit requires strict intelligence and rescue deadline',(){final s=DualState();s.place='Dungeon';final spirit={'id':'fox','intelligence':5};expect(s.capture(spirit),false);s.intelligence=6;expect(s.capture(spirit),true);s.rewardExam('a',true);s.resolveFates([{'person':'x','deadline':1}]);expect(s.deadStudents.contains('x'),true);});
 test('racial techniques must be acquired; drain, healing and sealing work',(){final s=DualState();final enemy={'id':'v','hp':50,'attack':4,'defense':0,'xp':20};final drain={'id':'bite','type':'drain','magic':false,'cost':1,'damage':8};s.startBattle(0,50);expect(s.action(drain,enemy),contains('adquirido'));s.skills.add('bite');s.hp=10;s.action(drain,enemy);expect(s.enemyHp,lessThan(50));s.skills.add('seal');s.action({'id':'seal','type':'hypnosis','magic':true,'cost':1,'damage':4},enemy);expect(s.enemyWeakTurns,1);final copy=DualState.fromJson(s.toJson());expect(copy.enemyWeakTurns,1);});
 test('student techniques become available with completed classes',(){final s=DualState();final sk={'minClasses':3};expect(s.skillAvailable(sk),false);for(var i=0;i<3;i++){s.rewardExam('l'+i.toString(),true);}expect(s.skillAvailable(sk),true);expect(s.skillAvailable({'minClasses':6}),false);});
 test('world travel, reading once and exercise cap',(){final s=DualState();expect(s.travel(),true);expect(s.world,'trade');s.place='Mercado';expect(s.travel(),false);expect(s.read('book',0,5),true);expect(s.read('book',0,5),false);for(var i=1;i<5;i++){s.read('book',i,5);}expect(s.intelligence,10);expect(s.workout('2026-11-27'),true);expect(s.workout('2026-11-27'),false);expect(s.workout('2026-11-26'),false);expect(s.strength,6);});
 test('cash is conserved and skills cannot be purchased twice',(){final s=DualState();s.commission();final r=s.trade(3,12,2,5,2)!;expect(r['profit'],12);expect(s.cash,37);expect(s.stock,1);s.appraised.add('shield');expect(s.buySkill('shield',30),true);expect(s.buySkill('shield',30),false);expect(s.cash,7);});
 test('starts powerless and choices persist, gate secrets, and cannot farm trust',(){final s=DualState();expect(s.skills,isEmpty);expect(s.reputation,-30);final e={'id':'meeting','world':'school','place':'Dormitorio','person':'lyra','choices':[{'id':'help','trust':8,'affection':3,'flag':'promise','outcome':'Gracias'}]};final ch=(e['choices'] as List).first as Map;expect(s.eligible(e),true);expect(s.chooseEvent(e,ch),true);expect(s.chooseEvent(e,ch),false);expect(s.relationship('lyra'),8);final saved=DualState.fromJson(s.toJson());expect(saved.flags.contains('promise'),true);expect(saved.warmth('lyra'),3);expect(saved.eligible(e),false);});
 test('exams unlock rewards once and persisted state survives',(){final s=DualState();expect(s.rewardExam('a',false),0);expect(s.rewardExam('a',true),90);expect(s.rewardExam('a',true),90);expect(s.cash,0);expect(s.claimGuild('a'),90);expect(s.claimGuild('a'),0);final copy=DualState.fromJson(s.toJson());expect(copy.grades['a'],90);expect(copy.cash,90);});
}
